class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    data = @packer ? @packer.dump(payload) : payload
    @store[key] = { payload: data, stale: stale }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    payload = @packer ? @packer.load(entry[:payload]) : entry[:payload]
    payload
  end

  def sweep
    @store.delete_if { |_, entry| entry[:stale] }
  end
end
```

