class Registry
  def initialize
    @objects = []
    @seen = {}
  end

  def register(obj)
    unless @seen.key?(obj.object_id)
      @objects << obj
      @seen[obj.object_id] = true
    end
    self
  end

  def registered?(obj)
    @seen.key?(obj.object_id)
  end

  def size
    @objects.size
  end

  def to_a
    @objects.dup
  end
end
